/**
 * UTF-8 helpers over Uint8Array, hand-rolled (no runtime built-ins required).
 *
 * Two decoders are provided:
 *   - `utf8Decode`          strict UTF-8, invalid bytes -> U+FFFD (WHATWG style)
 *   - `utf8DecodeSurrogateEscape`
 *                           strict UTF-8, every byte that is not part of a
 *                           well-formed sequence becomes U+DC00|byte, which is
 *                           exactly CPython's PEP-383 `surrogateescape` error
 *                           handler. This is what CPython uses to turn the raw
 *                           `argv` bytes into `str`, so it is what we need in
 *                           order to reproduce the reference program.
 *
 * The encoder is WTF-8 flavoured: lone surrogates are encoded as their 3-byte
 * form instead of raising, mirroring the fact that Python's json module never
 * throws on a lone surrogate (it emits the \udcXX escape instead).
 */

/**
 * Encode a JS string to UTF-8 bytes.
 * Lone surrogates are encoded in their 3-byte (WTF-8) form rather than throwing.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function utf8Encode(str) {
  const n = str.length;
  // Worst case is 3 bytes per UTF-16 code unit (a surrogate pair is 2 units
  // and yields 4 bytes, so 3/unit is a safe upper bound).
  const buf = new Uint8Array(n * 3);
  let o = 0;
  for (let i = 0; i < n; i++) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < n) {
      const lo = str.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      }
    }
    if (cp < 0x80) {
      buf[o++] = cp;
    } else if (cp < 0x800) {
      buf[o++] = 0xc0 | (cp >> 6);
      buf[o++] = 0x80 | (cp & 0x3f);
    } else if (cp < 0x10000) {
      buf[o++] = 0xe0 | (cp >> 12);
      buf[o++] = 0x80 | ((cp >> 6) & 0x3f);
      buf[o++] = 0x80 | (cp & 0x3f);
    } else {
      buf[o++] = 0xf0 | (cp >> 18);
      buf[o++] = 0x80 | ((cp >> 12) & 0x3f);
      buf[o++] = 0x80 | ((cp >> 6) & 0x3f);
      buf[o++] = 0x80 | (cp & 0x3f);
    }
  }
  return buf.subarray(0, o);
}

/**
 * Encode a string that is known to contain only code points <= U+00FF.
 * Each code unit becomes one byte. Useful for the JWS signing input, which is
 * pure ASCII by construction.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function latin1Encode(str) {
  const out = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) out[i] = str.charCodeAt(i) & 0xff;
  return out;
}

/**
 * Encode an ASCII-only string. Throws if a code unit is >= 0x80 so that callers
 * cannot silently corrupt data.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function asciiEncode(str) {
  const out = new Uint8Array(str.length);
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c > 0x7f) throw new RangeError('asciiEncode: non-ASCII code unit ' + c);
    out[i] = c;
  }
  return out;
}

/**
 * Length in bytes of the well-formed UTF-8 sequence starting at `i`, or 0 when
 * the bytes at `i` do not begin a well-formed sequence.
 *
 * Rejects: continuation bytes in lead position, 0xC0/0xC1 (overlong two-byte),
 * 0xF5..0xFF (beyond U+10FFFF), truncated sequences, overlong three/four-byte
 * forms and UTF-8-encoded surrogates (0xED 0xA0..0xBF ...).
 *
 * @param {Uint8Array} bytes
 * @param {number} i
 * @returns {number} 0, 1, 2, 3 or 4
 */
function sequenceLength(bytes, i) {
  const b0 = bytes[i];
  if (b0 < 0x80) return 1;
  if (b0 < 0xc2) return 0; // continuation byte, or overlong 2-byte lead
  const n = bytes.length;
  if (b0 < 0xe0) {
    if (i + 1 >= n) return 0;
    const b1 = bytes[i + 1];
    if ((b1 & 0xc0) !== 0x80) return 0;
    return 2;
  }
  if (b0 < 0xf0) {
    if (i + 2 >= n) return 0;
    const b1 = bytes[i + 1];
    const b2 = bytes[i + 2];
    if ((b1 & 0xc0) !== 0x80 || (b2 & 0xc0) !== 0x80) return 0;
    if (b0 === 0xe0 && b1 < 0xa0) return 0; // overlong
    if (b0 === 0xed && b1 > 0x9f) return 0; // encoded surrogate
    return 3;
  }
  if (b0 < 0xf5) {
    if (i + 3 >= n) return 0;
    const b1 = bytes[i + 1];
    const b2 = bytes[i + 2];
    const b3 = bytes[i + 3];
    if ((b1 & 0xc0) !== 0x80 || (b2 & 0xc0) !== 0x80 || (b3 & 0xc0) !== 0x80) return 0;
    if (b0 === 0xf0 && b1 < 0x90) return 0; // overlong
    if (b0 === 0xf4 && b1 > 0x8f) return 0; // > U+10FFFF
    return 4;
  }
  return 0;
}

/**
 * Decode the well-formed sequence of length `len` starting at `i`.
 *
 * @param {Uint8Array} bytes
 * @param {number} i
 * @param {number} len
 * @returns {number} code point
 */
function decodeSequence(bytes, i, len) {
  switch (len) {
    case 1:
      return bytes[i];
    case 2:
      return ((bytes[i] & 0x1f) << 6) | (bytes[i + 1] & 0x3f);
    case 3:
      return ((bytes[i] & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f);
    default:
      return (
        ((bytes[i] & 0x07) << 18) |
        ((bytes[i + 1] & 0x3f) << 12) |
        ((bytes[i + 2] & 0x3f) << 6) |
        (bytes[i + 3] & 0x3f)
      );
  }
}

/**
 * Append a code point to an array of UTF-16 code units.
 *
 * @param {number[]} units
 * @param {number} cp
 */
function pushCodePoint(units, cp) {
  if (cp < 0x10000) {
    units.push(cp);
  } else {
    const v = cp - 0x10000;
    units.push(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
  }
}

/**
 * Turn an array of UTF-16 code units into a string without blowing the
 * argument limit of String.fromCharCode.
 *
 * @param {number[]} units
 * @returns {string}
 */
function unitsToString(units) {
  const CHUNK = 4096;
  if (units.length <= CHUNK) return String.fromCharCode.apply(null, units);
  let out = '';
  for (let i = 0; i < units.length; i += CHUNK) {
    out += String.fromCharCode.apply(null, units.slice(i, i + CHUNK));
  }
  return out;
}

/**
 * Strict UTF-8 decode; each byte that is not part of a well-formed sequence is
 * mapped to U+DC00|byte (CPython's PEP-383 `surrogateescape`). Recovery is
 * byte-at-a-time, which is what CPython does: `b'\xed\xa0\x80'` decodes to
 * three separate escapes, and `b'\xc3\xa9\xffA'` decodes to `'é\udcffA'`.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function utf8DecodeSurrogateEscape(bytes) {
  const units = [];
  let i = 0;
  while (i < bytes.length) {
    const len = sequenceLength(bytes, i);
    if (len === 0) {
      units.push(0xdc00 | bytes[i]);
      i += 1;
    } else {
      pushCodePoint(units, decodeSequence(bytes, i, len));
      i += len;
    }
  }
  return unitsToString(units);
}

/**
 * Strict UTF-8 decode with U+FFFD substitution (one per offending byte).
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function utf8Decode(bytes) {
  const units = [];
  let i = 0;
  while (i < bytes.length) {
    const len = sequenceLength(bytes, i);
    if (len === 0) {
      units.push(0xfffd);
      i += 1;
    } else {
      pushCodePoint(units, decodeSequence(bytes, i, len));
      i += len;
    }
  }
  return unitsToString(units);
}

/**
 * base64 / base64url encoding and decoding over Uint8Array.
 *
 * `base64urlEncode` produces the JWS flavour: '+' -> '-', '/' -> '_' and all
 * '=' padding stripped (RFC 7515 §2).
 */

const STD_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const URL_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

/**
 * Build a reverse lookup table for a 64 character alphabet.
 *
 * @param {string} alphabet
 * @returns {Int16Array} 128-entry table mapping char code -> value, or -1
 */
function reverseTable(alphabet) {
  const t = new Int16Array(128).fill(-1);
  for (let i = 0; i < alphabet.length; i++) t[alphabet.charCodeAt(i)] = i;
  return t;
}

const URL_REVERSE = reverseTable(URL_ALPHABET);
const STD_REVERSE = reverseTable(STD_ALPHABET);

/**
 * Core encoder.
 *
 * @param {Uint8Array} bytes
 * @param {string} alphabet
 * @param {boolean} pad
 * @returns {string}
 */
function encodeWith(bytes, alphabet, pad) {
  const n = bytes.length;
  const full = n - (n % 3);
  const parts = [];
  let chunk = '';
  for (let i = 0; i < full; i += 3) {
    const v = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    chunk +=
      alphabet[(v >> 18) & 63] + alphabet[(v >> 12) & 63] + alphabet[(v >> 6) & 63] + alphabet[v & 63];
    if (chunk.length >= 8192) {
      parts.push(chunk);
      chunk = '';
    }
  }
  const rem = n - full;
  if (rem === 1) {
    const v = bytes[full] << 16;
    chunk += alphabet[(v >> 18) & 63] + alphabet[(v >> 12) & 63];
    if (pad) chunk += '==';
  } else if (rem === 2) {
    const v = (bytes[full] << 16) | (bytes[full + 1] << 8);
    chunk += alphabet[(v >> 18) & 63] + alphabet[(v >> 12) & 63] + alphabet[(v >> 6) & 63];
    if (pad) chunk += '=';
  }
  parts.push(chunk);
  return parts.join('');
}

/**
 * Standard base64 with '=' padding.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function base64Encode(bytes) {
  return encodeWith(bytes, STD_ALPHABET, true);
}

/**
 * base64url without padding, as used by JWS/JWT.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function base64urlEncode(bytes) {
  return encodeWith(bytes, URL_ALPHABET, false);
}

/**
 * Core decoder; ignores '=' padding and accepts unpadded input.
 *
 * @param {string} text
 * @param {Int16Array} table
 * @returns {Uint8Array}
 */
function decodeWith(text, table) {
  let clean = '';
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c === 0x3d) continue; // '='
    if (c > 127 || table[c] < 0) throw new Error('invalid base64 character at index ' + i);
    clean += text[i];
  }
  const n = clean.length;
  if (n % 4 === 1) throw new Error('invalid base64 length');
  const outLen = Math.floor((n * 3) / 4);
  const out = new Uint8Array(outLen);
  let o = 0;
  let acc = 0;
  let bits = 0;
  for (let i = 0; i < n; i++) {
    acc = (acc << 6) | table[clean.charCodeAt(i)];
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[o++] = (acc >> bits) & 0xff;
    }
  }
  return out.subarray(0, o);
}

/**
 * Decode standard base64 (padding optional).
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function base64Decode(text) {
  return decodeWith(text, STD_REVERSE);
}

/**
 * Decode base64url (padding optional). Provided for round-trip self-tests.
 *
 * @param {string} text
 * @returns {Uint8Array}
 */
export function base64urlDecode(text) {
  return decodeWith(text, URL_REVERSE);
}

/**
 * SHA-256 (FIPS 180-4) implemented from scratch in pure JavaScript.
 *
 * All arithmetic is done on 32-bit unsigned words; every expression that can
 * overflow or go negative is normalised with `>>> 0`.
 *
 * Exposes a streaming `Sha256` class and a one-shot `sha256()` helper.
 */

/** Block size in bytes. */
export const BLOCK_SIZE = 64;

/** Digest size in bytes. */
export const DIGEST_SIZE = 32;

/**
 * Initial hash value H(0): the first 32 bits of the fractional parts of the
 * square roots of the first eight primes (2, 3, 5, 7, 11, 13, 17, 19).
 */
export const H_INIT = Object.freeze([
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]);

/**
 * Round constants K: the first 32 bits of the fractional parts of the cube
 * roots of the first sixty-four primes (2 .. 311).
 */
export const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

/**
 * Rotate a 32-bit word right by n bits (0 < n < 32).
 *
 * @param {number} x
 * @param {number} n
 * @returns {number}
 */
function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

/**
 * Streaming SHA-256.
 *
 * Usage: `new Sha256().update(a).update(b).digest()`
 */
export class Sha256 {
  constructor() {
    /** @type {Uint32Array} running state */
    this._h = Uint32Array.from(H_INIT);
    /** @type {Uint8Array} partial block buffer */
    this._buf = new Uint8Array(BLOCK_SIZE);
    /** @type {number} bytes currently held in _buf */
    this._bufLen = 0;
    /** @type {number} total message length in bytes */
    this._total = 0;
    /** @type {Uint32Array} message schedule, reused across blocks */
    this._w = new Uint32Array(64);
    /** @type {boolean} */
    this._done = false;
  }

  /**
   * Absorb more message bytes.
   *
   * @param {Uint8Array} bytes
   * @returns {Sha256} this, for chaining
   */
  update(bytes) {
    if (this._done) throw new Error('Sha256: update() after digest()');
    let off = 0;
    const n = bytes.length;
    this._total += n;

    if (this._bufLen > 0) {
      const need = BLOCK_SIZE - this._bufLen;
      const take = n < need ? n : need;
      this._buf.set(bytes.subarray(0, take), this._bufLen);
      this._bufLen += take;
      off = take;
      if (this._bufLen === BLOCK_SIZE) {
        this._compress(this._buf, 0);
        this._bufLen = 0;
      }
    }

    while (n - off >= BLOCK_SIZE) {
      this._compress(bytes, off);
      off += BLOCK_SIZE;
    }

    if (off < n) {
      this._buf.set(bytes.subarray(off), 0);
      this._bufLen = n - off;
    }
    return this;
  }

  /**
   * Finalise and return the 32-byte digest (big-endian word order).
   *
   * @returns {Uint8Array}
   */
  digest() {
    if (this._done) throw new Error('Sha256: digest() called twice');
    this._done = true;

    const total = this._total;
    // 1 byte of 0x80 plus 8 bytes of length, rounded up to a whole block.
    const tailLen = (this._bufLen + 9 + 63) & ~63;
    const tail = new Uint8Array(tailLen);
    tail.set(this._buf.subarray(0, this._bufLen), 0);
    tail[this._bufLen] = 0x80;

    // 64-bit big-endian bit length. `total * 8` is exact for any message that
    // fits in memory (< 2^53), and ToUint32 gives the low word.
    const bits = total * 8;
    const hi = Math.floor(bits / 4294967296) >>> 0;
    const lo = bits >>> 0;
    const p = tailLen - 8;
    tail[p] = (hi >>> 24) & 0xff;
    tail[p + 1] = (hi >>> 16) & 0xff;
    tail[p + 2] = (hi >>> 8) & 0xff;
    tail[p + 3] = hi & 0xff;
    tail[p + 4] = (lo >>> 24) & 0xff;
    tail[p + 5] = (lo >>> 16) & 0xff;
    tail[p + 6] = (lo >>> 8) & 0xff;
    tail[p + 7] = lo & 0xff;

    for (let off = 0; off < tailLen; off += BLOCK_SIZE) this._compress(tail, off);

    const h = this._h;
    const out = new Uint8Array(DIGEST_SIZE);
    for (let i = 0; i < 8; i++) {
      const v = h[i];
      out[i * 4] = (v >>> 24) & 0xff;
      out[i * 4 + 1] = (v >>> 16) & 0xff;
      out[i * 4 + 2] = (v >>> 8) & 0xff;
      out[i * 4 + 3] = v & 0xff;
    }
    return out;
  }

  /**
   * Compress one 64-byte block located at `off` inside `m`.
   *
   * @param {Uint8Array} m
   * @param {number} off
   */
  _compress(m, off) {
    const w = this._w;
    for (let t = 0, o = off; t < 16; t++, o += 4) {
      w[t] = ((m[o] << 24) | (m[o + 1] << 16) | (m[o + 2] << 8) | m[o + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const x = w[t - 15];
      const y = w[t - 2];
      const s0 = (rotr(x, 7) ^ rotr(x, 18) ^ (x >>> 3)) >>> 0;
      const s1 = (rotr(y, 17) ^ rotr(y, 19) ^ (y >>> 10)) >>> 0;
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }

    const h = this._h;
    let a = h[0];
    let b = h[1];
    let c = h[2];
    let d = h[3];
    let e = h[4];
    let f = h[5];
    let g = h[6];
    let hh = h[7];

    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const T1 = (hh + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const T2 = (S0 + maj) >>> 0;
      hh = g;
      g = f;
      f = e;
      e = (d + T1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (T1 + T2) >>> 0;
    }

    h[0] = (h[0] + a) >>> 0;
    h[1] = (h[1] + b) >>> 0;
    h[2] = (h[2] + c) >>> 0;
    h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0;
    h[5] = (h[5] + f) >>> 0;
    h[6] = (h[6] + g) >>> 0;
    h[7] = (h[7] + hh) >>> 0;
  }
}

/**
 * One-shot SHA-256.
 *
 * @param {Uint8Array} bytes
 * @returns {Uint8Array} 32-byte digest
 */
export function sha256(bytes) {
  return new Sha256().update(bytes).digest();
}

/**
 * Hex rendering of a byte array (lowercase). Handy for self-tests.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function toHex(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += bytes[i].toString(16).padStart(2, '0');
  return s;
}

/**
 * Descriptor consumed by the generic HMAC implementation.
 */
export const SHA256 = Object.freeze({
  name: 'sha256',
  blockSize: BLOCK_SIZE,
  digestSize: DIGEST_SIZE,
  create: () => new Sha256(),
  digest: sha256,
});

/**
 * HMAC (RFC 2104) over an injected hash primitive.
 *
 * The primitive must expose `{ blockSize, digest(bytes), create() }` where
 * `create()` returns a streaming object with `update(bytes)` / `digest()`.
 * `SHA256` from ../hash/sha256.mjs satisfies that contract.
 */

import { SHA256 } from './sha256.mjs';

const IPAD = 0x36;
const OPAD = 0x5c;

/**
 * Derive the block-sized key K0: hash the key when it is longer than the block
 * size, then right-zero-pad to exactly one block.
 *
 * @param {{blockSize: number, digest: (b: Uint8Array) => Uint8Array}} primitive
 * @param {Uint8Array} key
 * @returns {Uint8Array} block-sized key
 */
function normalizeKey(primitive, key) {
  const block = new Uint8Array(primitive.blockSize); // zero filled
  if (key.length > primitive.blockSize) {
    block.set(primitive.digest(key), 0);
  } else {
    block.set(key, 0);
  }
  return block;
}

/**
 * Generic HMAC.
 *
 * @param {{blockSize: number, digest: Function, create: Function}} primitive
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} the MAC
 */
export function hmac(primitive, key, message) {
  const k0 = normalizeKey(primitive, key);
  const blockSize = primitive.blockSize;

  const inner = new Uint8Array(blockSize);
  const outer = new Uint8Array(blockSize);
  for (let i = 0; i < blockSize; i++) {
    inner[i] = k0[i] ^ IPAD;
    outer[i] = k0[i] ^ OPAD;
  }

  const innerDigest = primitive.create().update(inner).update(message).digest();
  return primitive.create().update(outer).update(innerDigest).digest();
}

/**
 * HMAC-SHA-256.
 *
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} 32-byte MAC
 */
export function hmacSha256(key, message) {
  return hmac(SHA256, key, message);
}

/**
 * A serializer that reproduces CPython's
 *
 *     json.dumps(obj, separators=(',', ':'), ensure_ascii=True)
 *
 * byte for byte.
 *
 * Escaping rules (per UTF-16 code unit, which is exactly how CPython's
 * `py_encode_basestring_ascii` behaves once you account for surrogate pairs):
 *
 *   0x22 '"'  -> \"
 *   0x5c '\'  -> \\
 *   0x08      -> \b
 *   0x09      -> \t
 *   0x0a      -> \n
 *   0x0c      -> \f
 *   0x0d      -> \r
 *   0x20..0x7e (other than the two above) -> emitted literally; note '/' is NOT
 *              escaped, and 0x0b is NOT \v
 *   everything else -> \uXXXX with four LOWERCASE hex digits
 *
 * Astral characters therefore come out as their two surrogate escapes, and a
 * lone surrogate (which is exactly what CPython's `surrogateescape` argv
 * decoding produces for invalid UTF-8 bytes) comes out as a single \udcXX
 * escape rather than raising.
 */

/** Two-character escapes; every other special code unit uses the \uXXXX form. */
const SHORT_ESCAPES = Object.freeze({
  8: '\\b',
  9: '\\t',
  10: '\\n',
  12: '\\f',
  13: '\\r',
  34: '\\"',
  92: '\\\\',
});

/**
 * Escape the *body* of a JSON string (no surrounding quotes).
 *
 * @param {string} s
 * @returns {string}
 */
export function escapeString(s) {
  let out = '';
  let plainStart = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0x20 && c <= 0x7e && c !== 0x22 && c !== 0x5c) continue;
    if (plainStart < i) out += s.slice(plainStart, i);
    const short = SHORT_ESCAPES[c];
    out += short !== undefined ? short : '\\u' + c.toString(16).padStart(4, '0');
    plainStart = i + 1;
  }
  if (plainStart === 0) return s;
  if (plainStart < s.length) out += s.slice(plainStart);
  return out;
}

/**
 * Render a JS string as a JSON string literal, including the quotes.
 *
 * @param {string} s
 * @returns {string}
 */
export function encodeString(s) {
  return '"' + escapeString(s) + '"';
}

/**
 * Render a number the way CPython's json module would.
 *
 * CPython uses `repr(int)` for ints and `float.__repr__` for floats, and emits
 * the bare tokens Infinity / -Infinity / NaN (which are not legal JSON, but are
 * what json.dumps produces by default).
 *
 * @param {number} n
 * @returns {string}
 */
function encodeNumber(n) {
  if (Number.isNaN(n)) return 'NaN';
  if (n === Infinity) return 'Infinity';
  if (n === -Infinity) return '-Infinity';
  return String(n);
}

/**
 * Serialize a value with compact separators and ensure_ascii semantics.
 *
 * Supported: string, number, boolean, null/undefined (-> null), Array, Map and
 * plain objects (own enumerable keys, insertion order, exactly like a Python
 * dict). Non-string Map/object keys are coerced with String() the way
 * json.dumps coerces simple key types.
 *
 * @param {*} value
 * @returns {string}
 */
export function dumps(value) {
  if (value === null || value === undefined) return 'null';
  const t = typeof value;
  if (t === 'string') return encodeString(value);
  if (t === 'number') return encodeNumber(value);
  if (t === 'boolean') return value ? 'true' : 'false';
  if (t === 'bigint') return value.toString();
  if (Array.isArray(value)) {
    let out = '[';
    for (let i = 0; i < value.length; i++) {
      if (i > 0) out += ',';
      out += dumps(value[i]);
    }
    return out + ']';
  }
  if (value instanceof Map) {
    let out = '{';
    let first = true;
    for (const [k, v] of value) {
      if (!first) out += ',';
      first = false;
      out += encodeString(typeof k === 'string' ? k : String(k)) + ':' + dumps(v);
    }
    return out + '}';
  }
  if (t === 'object') {
    let out = '{';
    let first = true;
    for (const k of Object.keys(value)) {
      if (!first) out += ',';
      first = false;
      out += encodeString(k) + ':' + dumps(value[k]);
    }
    return out + '}';
  }
  throw new TypeError('Object of type ' + t + ' is not JSON serializable');
}

/**
 * Algorithm registry, mirroring `jose.constants.ALGORITHMS` and the signer
 * lookup that python-jose performs inside `jws._sign`.
 *
 * Only the HMAC family is needed here; the table is shaped so that additional
 * families could be slotted in without touching the JWS layer.
 */

import { hmac } from '../hash/hmac.mjs';
import { SHA256 } from '../hash/sha256.mjs';

/** Algorithm name constants, as exposed by python-jose. */
export const ALGORITHMS = Object.freeze({
  NONE: 'none',
  HS256: 'HS256',
  HS384: 'HS384',
  HS512: 'HS512',
});

/** The algorithm python-jose falls back to when none is supplied. */
export const DEFAULT_ALGORITHM = ALGORITHMS.HS256;

/**
 * name -> { name, kind, sign(keyBytes, messageBytes) -> Uint8Array }
 */
const REGISTRY = new Map([
  [
    ALGORITHMS.HS256,
    Object.freeze({
      name: ALGORITHMS.HS256,
      kind: 'hmac',
      primitive: SHA256,
      sign: (key, message) => hmac(SHA256, key, message),
    }),
  ],
]);

/**
 * Look up a signer by JWS `alg` name.
 *
 * @param {string} name
 * @returns {{name: string, kind: string, sign: (k: Uint8Array, m: Uint8Array) => Uint8Array}}
 */
export function getAlgorithm(name) {
  const found = REGISTRY.get(name);
  if (!found) throw new Error('Algorithm not supported: ' + name);
  return found;
}

/**
 * @returns {string[]} names of all supported algorithms
 */
export function supportedAlgorithms() {
  return [...REGISTRY.keys()];
}

/**
 * JWS compact serialization (RFC 7515), matching python-jose's `jws.sign`.
 *
 * The header python-jose emits for a bare `jwt.encode(claims, key)` call is
 * exactly `{"alg":"HS256","typ":"JWT"}` in that key order, with compact
 * separators and ensure_ascii — hence the shared python-json serializer.
 */

import { base64urlEncode } from '../bytes/base64url.mjs';
import { latin1Encode, utf8Encode } from '../bytes/utf8.mjs';
import { dumps } from '../json/python-json.mjs';
import { getAlgorithm, DEFAULT_ALGORITHM } from './algorithms.mjs';

/**
 * Build the JOSE header object. Key order is significant: python-jose emits
 * `alg` before `typ`.
 *
 * @param {string} algorithm
 * @param {Object<string, *>} [extra] additional header members
 * @returns {Object<string, *>}
 */
export function buildHeader(algorithm, extra) {
  const header = { alg: algorithm, typ: 'JWT' };
  if (extra) for (const k of Object.keys(extra)) header[k] = extra[k];
  return header;
}

/**
 * base64url(utf8(python-json(value))).
 *
 * Because ensure_ascii is on, the JSON text is always pure ASCII; the UTF-8
 * encoder is used anyway so the module stays correct for any input.
 *
 * @param {*} value
 * @returns {string}
 */
export function encodeSegment(value) {
  return base64urlEncode(utf8Encode(dumps(value)));
}

/**
 * The bytes that get signed: ASCII of `<header>.<payload>`.
 *
 * @param {string} headerSegment
 * @param {string} payloadSegment
 * @returns {{text: string, bytes: Uint8Array}}
 */
export function signingInput(headerSegment, payloadSegment) {
  const text = headerSegment + '.' + payloadSegment;
  // Both segments are base64url, so every code unit is < 0x80.
  return { text, bytes: latin1Encode(text) };
}

/**
 * Sign a claims object and return the compact JWS serialization.
 *
 * @param {*} claims        payload object (or any JSON-serializable value)
 * @param {Uint8Array} key  raw key bytes
 * @param {string} [algorithm='HS256']
 * @param {Object<string, *>} [headers] extra JOSE header members
 * @returns {string} `header.payload.signature`
 */
export function sign(claims, key, algorithm = DEFAULT_ALGORITHM, headers = undefined) {
  const signer = getAlgorithm(algorithm);
  const headerSegment = encodeSegment(buildHeader(algorithm, headers));
  const payloadSegment = encodeSegment(claims);
  const input = signingInput(headerSegment, payloadSegment);
  const signature = base64urlEncode(signer.sign(key, input.bytes));
  return input.text + '.' + signature;
}

/**
 * `jose.jwt.encode` facade.
 *
 * python-jose's signature is
 *
 *     jwt.encode(claims, key, algorithm=ALGORITHMS.HS256, headers=None,
 *                access_token=None)
 *
 * and for a str key it uses the key's UTF-8 bytes as the HMAC secret.
 */

import { utf8Encode } from '../bytes/utf8.mjs';
import { DEFAULT_ALGORITHM } from './algorithms.mjs';
import { sign } from './jws.mjs';

/**
 * Coerce a key to raw bytes. Strings are UTF-8 encoded, byte arrays pass
 * through untouched.
 *
 * @param {string|Uint8Array} key
 * @returns {Uint8Array}
 */
export function keyToBytes(key) {
  if (key instanceof Uint8Array) return key;
  if (typeof key === 'string') return utf8Encode(key);
  throw new TypeError('Unsupported key type');
}

/**
 * Encode a claims object as a signed compact JWT.
 *
 * @param {*} claims
 * @param {string|Uint8Array} key
 * @param {string} [algorithm='HS256']
 * @param {Object<string, *>} [headers]
 * @returns {string}
 */
export function encode(claims, key, algorithm = DEFAULT_ALGORITHM, headers = undefined) {
  return sign(claims, keyToBytes(key), algorithm, headers);
}

/** Namespace object so callers can write `jwt.encode(...)` like the Python source. */
export const jwt = Object.freeze({ encode });

export default jwt;

/**
 * Error types and message formatting shared by the argparse port.
 *
 * Mirrors `argparse.ArgumentError`, `argparse._get_action_name` and the
 * `parser.error()` / `parser.exit()` envelope:
 *
 *     <usage line>
 *     <prog>: error: <message>
 *
 * written to stderr with exit status 2.
 */

/**
 * Raised for problems attributable to a specific action, e.g.
 * `argument --payload: expected one argument`.
 */
export class ArgumentError extends Error {
  /**
   * @param {{optionStrings?: string[], metavar?: string|null, dest?: string|null, choices?: *}|null} action
   * @param {string} message
   */
  constructor(action, message) {
    const name = getActionName(action);
    super(name === null ? message : 'argument ' + name + ': ' + message);
    this.name = 'ArgumentError';
    this.argumentName = name;
    this.rawMessage = message;
  }
}

/**
 * Raised instead of terminating the process, so that the entry point can flush
 * stdout naturally (calling process.exit() truncates pipe writes in Node).
 */
export class SystemExit extends Error {
  /**
   * @param {number} code
   */
  constructor(code) {
    super('SystemExit(' + code + ')');
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * argparse's `_get_action_name`.
 *
 * @param {*} action
 * @returns {string|null}
 */
export function getActionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings && action.optionStrings.length) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null && action.dest !== undefined) return action.dest;
  if (action.choices) return '{' + action.choices.join(',') + '}';
  return null;
}

/**
 * Escapes used by CPython's `repr()` for str.
 */
const REPR_SHORT = Object.freeze({ 9: '\\t', 10: '\\n', 13: '\\r', 92: '\\\\' });

/**
 * Approximate CPython `repr()` of a string, which is what the `%r` in
 * "ignored explicit argument %r" expands to.
 *
 * Quote selection follows CPython: single quotes unless the string contains a
 * single quote and no double quote.
 *
 * @param {string} s
 * @returns {string}
 */
export function pyRepr(s) {
  const quote = s.indexOf("'") !== -1 && s.indexOf('"') === -1 ? '"' : "'";
  const q = quote.charCodeAt(0);
  let out = quote;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    const short = REPR_SHORT[c];
    if (short !== undefined) {
      out += short;
    } else if (c === q) {
      out += '\\' + s[i];
    } else if (c < 0x20 || c === 0x7f) {
      out += '\\x' + c.toString(16).padStart(2, '0');
    } else if (c < 0x7f) {
      out += s[i];
    } else if (c <= 0x9f || (c >= 0xd800 && c <= 0xdfff)) {
      // C1 controls and lone surrogates are not printable
      out += c <= 0xff ? '\\x' + c.toString(16).padStart(2, '0') : '\\u' + c.toString(16).padStart(4, '0');
    } else {
      out += s[i];
    }
  }
  return out + quote;
}

/**
 * Build the two-line error block written to stderr.
 *
 * @param {string} usage   the usage text, already newline-terminated
 * @param {string} prog
 * @param {string} message
 * @returns {string}
 */
export function formatErrorBlock(usage, prog, message) {
  return usage + prog + ': error: ' + message + '\n';
}

/**
 * Thin stdout/stderr helpers plus terminal-width detection.
 *
 * Writes deliberately avoid `process.exit()`: in Node a pipe-backed stdout is
 * asynchronous, so exiting straight after a large `write` silently truncates
 * the output at 64 KiB. The entry point instead sets `process.exitCode` and
 * lets the event loop drain naturally.
 */

/**
 * Write to stdout, swallowing EPIPE/ENOSPC/EBADF the way CPython's
 * `print()` failure path still leaves the exit status alone here.
 *
 * @param {string} text
 */
export function writeStdout(text) {
  try {
    process.stdout.write(text);
  } catch {
    /* stdout closed or full: ignore, mirroring the reference's exit status */
  }
}

/**
 * Write to stderr, swallowing write errors.
 *
 * @param {string} text
 */
export function writeStderr(text) {
  try {
    process.stderr.write(text);
  } catch {
    /* ignore */
  }
}

/**
 * Parse an integer the way CPython's `int()` does for the COLUMNS lookup:
 * surrounding whitespace allowed, optional sign, decimal digits only.
 *
 * @param {string} text
 * @returns {number|null}
 */
function parsePythonInt(text) {
  const t = text.trim();
  if (!/^[+-]?[0-9]+$/.test(t)) return null;
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
}

/**
 * Reproduce `shutil.get_terminal_size().columns`: honour a positive integer in
 * $COLUMNS, otherwise ask the stdout terminal, otherwise fall back to 80.
 *
 * @returns {number}
 */
export function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined) {
    const n = parsePythonInt(env);
    if (n !== null && n > 0) return n;
  }
  const cols = process.stdout && process.stdout.isTTY ? process.stdout.columns : undefined;
  if (typeof cols === 'number' && cols > 0) return cols;
  return 80;
}
